# ============================================================================
# SPANISH CPI PROJECT: EXTENDED BACKTEST AND YEARLY COMPARISON
#
# Required inputs generated by the main script:
# ipc_serie_historica.csv
# ipc_backtest_detalle.csv
#
# This script does not refit the 600-tree Random Forest at each origin.
# It reuses the existing ARIMA, Random Forest, Naive, and seasonal-Naive backtest,
# then tests ETS, Theta, and drift-Naive on exactly the same forecast origins.
# It also evaluates bias correction and compares historical October–December
# forecasts issued from September for October, November, and December in
# previous years.
#
# Run Source from the project root, where the required CSV files are stored.
# ============================================================================

# ------------------------------- 0. PACKAGES -------------------------------
paquetes <- c("readr", "dplyr", "tidyr", "lubridate", "tibble", "forecast", "ranger")
faltan <- paquetes[!vapply(paquetes, requireNamespace, logical(1), quietly = TRUE)]
if (length(faltan) > 0) install.packages(faltan, repos = "https://cloud.r-project.org")

suppressPackageStartupMessages({
  library(readr)
  library(dplyr)
  library(tidyr)
  library(lubridate)
  library(tibble)
  library(forecast)
  library(ranger)
})

RESULTS_DIR <- file.path("results", "working")
dir.create(RESULTS_DIR, recursive = TRUE, showWarnings = FALSE)

# ----------------------------- 1. CONFIGURATION ---------------------------
VENTANA_SESGO <- 24L
MIN_ERRORES_SESGO <- 6L
N_ARBOLES <- 600L
SEMILLA <- 2026L
ANIO_INICIAL_TABLA <- 2000L

archivos <- c(
  serie = file.path(RESULTS_DIR, "ipc_serie_historica.csv"),
  backtest = file.path(RESULTS_DIR, "ipc_backtest_detalle.csv")
)
no_encontrados <- archivos[!file.exists(archivos)]
if (length(no_encontrados) > 0) {
  stop("Missing required file(s): ", paste(no_encontrados, collapse = ", "),
       ". Current directory: ", getwd(),
       ". Run from the project root containing both required CSV files.")
}

# -------------------------------- 2. DATA ----------------------------------
serie <- read_csv(archivos[["serie"]], show_col_types = FALSE) %>%
  mutate(
    fecha = as.Date(as.character(fecha)),
    ipc_interanual = suppressWarnings(as.numeric(ipc_interanual))
  ) %>%
  filter(!is.na(fecha), is.finite(ipc_interanual)) %>%
  arrange(fecha) %>%
  distinct(fecha, .keep_all = TRUE)

bt_original <- read_csv(archivos[["backtest"]], show_col_types = FALSE) %>%
  mutate(
    fecha_origen = as.Date(as.character(fecha_origen)),
    fecha_objetivo = as.Date(as.character(fecha_objetivo)),
    horizonte = as.integer(horizonte),
    prediccion = as.numeric(prediccion),
    real = as.numeric(real),
    error = as.numeric(error)
  ) %>%
  filter(
    !is.na(fecha_origen), !is.na(fecha_objetivo),
    is.finite(prediccion), is.finite(real), is.finite(error)
  ) %>%
  arrange(fecha_origen, horizonte, modelo)

if (nrow(serie) == 0 || nrow(bt_original) == 0) stop("The CSV files contain no valid observations.")
columnas_bt <- c("fecha_origen", "fecha_objetivo", "horizonte", "modelo", "prediccion", "real", "error")
if (!all(columnas_bt %in% names(bt_original))) {
  stop("Missing columns in ipc_backtest_detalle.csv: ",
       paste(setdiff(columnas_bt, names(bt_original)), collapse = ", "))
}

fechas <- serie$fecha
y <- as.numeric(serie$ipc_interanual)
ultima_fecha <- max(fechas)
ultimo_valor <- y[length(y)]
cat("\n============================================================\n")
cat("EXTENDED SPAIN CPI BACKTEST ANALYSIS\n")
cat("============================================================\n")
cat("Latest observation in the CSV data:", format(ultima_fecha, "%Y-%m"),
    "| year-over-year inflation =", round(ultimo_valor, 2), "%\n")
cat("Historical observations:", length(y),
    "| available backtest origins:", n_distinct(bt_original$fecha_origen), "\n")

# ----------------------- 3. ADDITIONAL MODELS ------------------------------
# Three complementary methods are evaluated at the same historical origins:
# ETS (exponential smoothing), Theta, and a random walk with drift.
pronosticos_nuevos <- function(y_train, h = 3L) {
  salida <- list()
  ts_train <- stats::ts(y_train, frequency = 12)

  salida[["ETS"]] <- tryCatch(
    as.numeric(forecast::forecast(forecast::ets(ts_train), h = h)$mean),
    error = function(e) rep(NA_real_, h)
  )
  salida[["Theta"]] <- tryCatch(
    as.numeric(forecast::thetaf(ts_train, h = h)$mean),
    error = function(e) rep(NA_real_, h)
  )
  salida[["Naive with Drift"]] <- tryCatch(
    as.numeric(forecast::rwf(ts_train, h = h, drift = TRUE)$mean),
    error = function(e) rep(NA_real_, h)
  )
  salida
}

origenes <- sort(unique(bt_original$fecha_origen))
lista_extra <- list()
contador <- 1L
for (fecha_origen_i in origenes) {
  # R may drop the Date class when iterating over a date vector with a for loop;
  # explicitly restoring it prevents Date/double type mismatches in bind_rows().
  fecha_origen_date <- as.Date(fecha_origen_i, origin = "1970-01-01")
  idx <- which(fechas == fecha_origen_date)
  if (length(idx) != 1L || idx < 60L) next
  fechas_obj <- seq.Date(from = fecha_origen_date, by = "month", length.out = 4L)[-1]
  idx_obj <- match(fechas_obj, fechas)
  # Evaluate only origins with all three observed October–December outcomes.
  if (anyNA(idx_obj)) next

  nuevos <- pronosticos_nuevos(y[seq_len(idx)], h = 3L)
  for (nombre in names(nuevos)) {
    vals <- nuevos[[nombre]]
    if (length(vals) != 3L) next
    for (hh in 1:3) {
      if (!is.finite(vals[hh])) next
      real_i <- y[idx_obj[hh]]
      lista_extra[[contador]] <- tibble(
        fecha_origen = fecha_origen_date,
        fecha_objetivo = as.Date(fechas_obj[hh]),
        horizonte = hh,
        modelo = nombre,
        prediccion = as.numeric(vals[hh]),
        real = as.numeric(real_i),
        error = as.numeric(real_i - vals[hh])
      )
      contador <- contador + 1L
    }
  }
}

bt_extra <- bind_rows(lista_extra)
if (nrow(bt_extra) == 0L) stop("ETS/Theta/Drift backtests could not be generated.")

# Keep the original model rows and append only the newly evaluated methods.
bt <- bind_rows(bt_original, bt_extra) %>%
  arrange(modelo, horizonte, fecha_origen)

write_csv(bt, file.path(RESULTS_DIR, "ipc_modelos_ampliados_backtest.csv"))
cat("Additional models:", paste(unique(bt_extra$modelo), collapse = ", "),
    "| additional forecasts:", nrow(bt_extra), "\n")

# ---------------- 4. OVERALL AND HORIZON-SPECIFIC METRICS ------------------
metricas <- bt %>%
  group_by(modelo) %>%
  summarise(
    MAE = mean(abs(error), na.rm = TRUE),
    RMSE = sqrt(mean(error^2, na.rm = TRUE)),
    observaciones = sum(is.finite(error)),
    .groups = "drop"
  ) %>% arrange(MAE)

metricas_h <- bt %>%
  group_by(modelo, horizonte) %>%
  summarise(
    MAE = mean(abs(error), na.rm = TRUE),
    RMSE = sqrt(mean(error^2, na.rm = TRUE)),
    observaciones = sum(is.finite(error)),
    .groups = "drop"
  ) %>% arrange(horizonte, MAE)

write_csv(metricas, file.path(RESULTS_DIR, "ipc_metricas_modelos_ampliados.csv"))
write_csv(metricas_h, file.path(RESULTS_DIR, "ipc_metricas_por_horizonte_ampliado.csv"))
cat("\n--- Model comparison (lower MAE is better) ---\n")
print(metricas %>% mutate(across(c(MAE, RMSE), ~ round(.x, 3))), n = Inf)
cat("\n--- Metrics by forecast horizon ---\n")
print(metricas_h %>% mutate(across(c(MAE, RMSE), ~ round(.x, 3))), n = Inf)

# ---------------- 5. BIAS CORRECTION AND LEAKAGE CHECKS --------------------
# See docs/METHODOLOGY.md for the rationale behind this step.
# the forecast origin (target date <= origin date). The mean uses up to the
# latest 24 observed errors for the same model and horizon.
calcular_sesgo <- function(datos_bt, modelo_i, horizonte_i, fecha_corte,
                           ventana = VENTANA_SESGO, minimo = MIN_ERRORES_SESGO) {
  previos <- datos_bt %>%
    filter(
      modelo == modelo_i,
      horizonte == horizonte_i,
      fecha_objetivo <= fecha_corte
    ) %>%
    arrange(fecha_objetivo, fecha_origen) %>%
    slice_tail(n = ventana)
  if (nrow(previos) < minimo) return(0)
  mean(previos$error, na.rm = TRUE)
}

bt$correccion_causal <- 0
for (i in seq_len(nrow(bt))) {
  bt$correccion_causal[i] <- calcular_sesgo(
    datos_bt = bt,
    modelo_i = bt$modelo[i],
    horizonte_i = bt$horizonte[i],
    fecha_corte = bt$fecha_origen[i]
  )
}
bt <- bt %>% mutate(
  prediccion_corregida = prediccion + correccion_causal,
  error_corregido = real - prediccion_corregida,
  abs_error = abs(error),
  abs_error_corregido = abs(error_corregido)
)

metricas_sesgo <- bt %>%
  group_by(modelo, horizonte) %>%
  summarise(
    n = n(),
    MAE_bruto = mean(abs_error, na.rm = TRUE),
    MAE_corregido = mean(abs_error_corregido, na.rm = TRUE),
    RMSE_bruto = sqrt(mean(error^2, na.rm = TRUE)),
    RMSE_corregido = sqrt(mean(error_corregido^2, na.rm = TRUE)),
    mejora_MAE_pct = 100 * (MAE_bruto - MAE_corregido) / MAE_bruto,
    .groups = "drop"
  ) %>% arrange(horizonte, MAE_bruto)
write_csv(metricas_sesgo, file.path(RESULTS_DIR, "ipc_evaluacion_correccion_sesgo_ampliada.csv"))

metricas_sesgo_global <- bt %>%
  group_by(modelo) %>%
  summarise(
    n = n(),
    MAE_bruto = mean(abs_error, na.rm = TRUE),
    MAE_corregido = mean(abs_error_corregido, na.rm = TRUE),
    RMSE_bruto = sqrt(mean(error^2, na.rm = TRUE)),
    RMSE_corregido = sqrt(mean(error_corregido^2, na.rm = TRUE)),
    mejora_MAE_pct = 100 * (MAE_bruto - MAE_corregido) / MAE_bruto,
    .groups = "drop"
  ) %>% arrange(MAE_bruto)
write_csv(metricas_sesgo_global, file.path(RESULTS_DIR, "ipc_resumen_correccion_modelos_ampliados.csv"))

cat("\n--- Does bias correction improve the rolling-origin backtest? ---\n")
print(metricas_sesgo %>% mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf)
cat("\n--- Aggregate effect of bias correction by model ---\n")
print(metricas_sesgo_global %>% mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf)

# -------------------- 6. OBSERVED OCT-NOV-DEC VALUES -----------------------
# Show observed year-over-year CPI rates for these months across years.
# This provides historical context but does not by itself measure MAE.
ipc_oct_dic_real <- serie %>%
  mutate(anio = year(fecha), mes_num = month(fecha)) %>%
  filter(anio >= ANIO_INICIAL_TABLA, mes_num %in% c(10L, 11L, 12L)) %>%
  mutate(mes = recode(as.character(mes_num), `10` = "October", `11` = "November", `12` = "December")) %>%
  select(anio, mes, ipc_interanual) %>%
  pivot_wider(names_from = mes, values_from = ipc_interanual) %>%
  arrange(anio)
write_csv(ipc_oct_dic_real, file.path(RESULTS_DIR, "ipc_valores_reales_oct_nov_dic_por_ano.csv"))
cat("\n--- Actual year-over-year CPI inflation by year (%) ---\n")
print(ipc_oct_dic_real %>% mutate(across(where(is.numeric), ~ round(.x, 2))), n = Inf)

# ----------------- 7. SEPTEMBER-ORIGIN ANNUAL VALIDATION ------------------
# Historical forecasts whose training data end in September and whose
# targets are October, November, or December of the same year.
prevision_otono <- bt %>%
  mutate(
    anio_origen = year(fecha_origen),
    mes_origen = month(fecha_origen),
    anio_objetivo = year(fecha_objetivo),
    mes_objetivo = month(fecha_objetivo)
  ) %>%
  filter(
    mes_origen == 9L,
    anio_objetivo == anio_origen,
    mes_objetivo %in% c(10L, 11L, 12L)
  ) %>%
  mutate(
    mes = recode(as.character(mes_objetivo), `10` = "October", `11` = "November", `12` = "December"),
    error_bruto = real - prediccion,
    error_absoluto_bruto = abs(error_bruto),
    error_corregido_anual = real - prediccion_corregida,
    error_absoluto_corregido = abs(error_corregido_anual)
  ) %>%
  select(
    anio = anio_origen, mes, fecha_origen, fecha_objetivo, horizonte, modelo,
    IPC_real = real, prediccion_bruta = prediccion, error_bruto,
    correccion_causal, prediccion_corregida, error_corregido_anual,
    error_absoluto_bruto, error_absoluto_corregido
  ) %>% arrange(anio, horizonte, modelo)

write_csv(prevision_otono, file.path(RESULTS_DIR, "ipc_backtest_oct_nov_dic_por_ano.csv"))
cat("\n--- Historical forecasts issued from September in previous years ---\n")
if (nrow(prevision_otono) > 0) {
  print(prevision_otono %>%
          mutate(across(c(IPC_real, prediccion_bruta, error_bruto,
                          correccion_causal, prediccion_corregida,
                          error_corregido_anual), ~ round(.x, 3))),
        n = Inf)
} else {
  cat("No autumn forecasts are available in the backtest. Check the date range of the CSV files.\n")
}

if (nrow(prevision_otono) > 0) {
  metricas_otono <- prevision_otono %>%
    group_by(modelo, horizonte, mes) %>%
    summarise(
      n = n(),
      MAE_bruto = mean(error_absoluto_bruto, na.rm = TRUE),
      MAE_corregido = mean(error_absoluto_corregido, na.rm = TRUE),
      RMSE_bruto = sqrt(mean(error_bruto^2, na.rm = TRUE)),
      RMSE_corregido = sqrt(mean(error_corregido_anual^2, na.rm = TRUE)),
      mejora_MAE_pct = 100 * (MAE_bruto - MAE_corregido) / MAE_bruto,
      .groups = "drop"
    ) %>% arrange(horizonte, MAE_bruto)
  write_csv(metricas_otono, file.path(RESULTS_DIR, "ipc_metricas_backtest_oct_nov_dic.csv"))
  cat("\n--- MAE/RMSE for historical October–December forecasts only ---\n")
  print(metricas_otono %>% mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf)
}

# ----------------------- 8. CURRENT MODEL FORECASTS ------------------------
# Fit every candidate model through the latest available observation.
# Reuse the Random Forest predictor definition from the main script.
crear_entrenamiento_rf <- function(y0, fechas0) {
  n0 <- length(y0)
  indices <- seq.int(13L, n0)
  mes <- month(fechas0[indices])
  tibble(
    objetivo = y0[indices],
    lag1 = y0[indices - 1L],
    lag2 = y0[indices - 2L],
    lag3 = y0[indices - 3L],
    lag6 = y0[indices - 6L],
    lag12 = y0[indices - 12L],
    media3 = vapply(indices, function(i) mean(y0[(i - 3L):(i - 1L)]), numeric(1)),
    media6 = vapply(indices, function(i) mean(y0[(i - 6L):(i - 1L)]), numeric(1)),
    sd6 = vapply(indices, function(i) stats::sd(y0[(i - 6L):(i - 1L)]), numeric(1)),
    sin_mes = sin(2 * pi * mes / 12),
    cos_mes = cos(2 * pi * mes / 12)
  )
}

pronosticar_rf_actual <- function(y0, fechas0, h = 3L) {
  ent <- crear_entrenamiento_rf(y0, fechas0)
  fit <- ranger::ranger(
    objetivo ~ ., data = as.data.frame(ent), num.trees = N_ARBOLES,
    min.node.size = 5, seed = SEMILLA, importance = "permutation"
  )
  historia <- y0
  salida <- numeric(h)
  for (j in seq_len(h)) {
    n0 <- length(historia)
    fecha_obj <- seq.Date(from = max(fechas0), by = "month", length.out = j + 1L)[j + 1L]
    mes <- month(fecha_obj)
    fila <- tibble(
      lag1 = historia[n0], lag2 = historia[n0 - 1L], lag3 = historia[n0 - 2L],
      lag6 = historia[n0 - 5L], lag12 = historia[n0 - 11L],
      media3 = mean(historia[(n0 - 2L):n0]),
      media6 = mean(historia[(n0 - 5L):n0]),
      sd6 = stats::sd(historia[(n0 - 5L):n0]),
      sin_mes = sin(2 * pi * mes / 12),
      cos_mes = cos(2 * pi * mes / 12)
    )
    salida[j] <- as.numeric(predict(fit, data = as.data.frame(fila))$predictions[1])
    historia <- c(historia, salida[j])
  }
  salida
}

fechas_futuras <- seq.Date(from = ultima_fecha, by = "month", length.out = 4L)[-1]
h <- length(fechas_futuras)
ts_y <- stats::ts(y, frequency = 12)

# ARIMA and Naive are reused; ETS, Theta, and drift are fitted here.
pronosticos_actuales <- list(
  "ARIMA" = tryCatch(as.numeric(forecast::forecast(forecast::auto.arima(
    ts_y, seasonal = TRUE, stepwise = TRUE, approximation = FALSE), h = h)$mean),
    error = function(e) rep(NA_real_, h)),
  "Naive" = rep(tail(y, 1), h),
  "Seasonal Naive (12)" = {
    hist0 <- y; out0 <- numeric(h)
    for (j in seq_len(h)) {
      idx0 <- length(hist0) - 11L
      out0[j] <- if (idx0 >= 1L) hist0[idx0] else tail(hist0, 1)
      hist0 <- c(hist0, out0[j])
    }
    out0
  },
  "ETS" = tryCatch(as.numeric(forecast::forecast(forecast::ets(ts_y), h = h)$mean),
    error = function(e) rep(NA_real_, h)),
  "Theta" = tryCatch(as.numeric(forecast::thetaf(ts_y, h = h)$mean),
    error = function(e) rep(NA_real_, h)),
  "Naive with Drift" = tryCatch(as.numeric(forecast::rwf(ts_y, h = h, drift = TRUE)$mean),
    error = function(e) rep(NA_real_, h)),
  "Random Forest" = tryCatch(pronosticar_rf_actual(y, fechas, h),
    error = function(e) {
      cat("Warning: Random Forest could not be computed for future months: ", conditionMessage(e), "\n", sep = "")
      rep(NA_real_, h)
    })
)

pron_actual_largo <- bind_rows(lapply(names(pronosticos_actuales), function(mod) {
  vv <- pronosticos_actuales[[mod]]
  tibble(
    fecha_objetivo = fechas_futuras,
    horizonte = seq_along(fechas_futuras),
    modelo = mod,
    prediccion_bruta = as.numeric(vv)
  )
})) %>% filter(is.finite(prediccion_bruta))

# Use historical errors observable at the latest data date to calculate
# a model- and horizon-specific correction. Recommend it only if it improves
# both the full backtest and the October–December backtest, when available.
pron_actual_largo <- pron_actual_largo %>% rowwise() %>%
  mutate(
    correccion_sesgo = calcular_sesgo(
      datos_bt = bt,
      modelo_i = modelo,
      horizonte_i = horizonte,
      fecha_corte = ultima_fecha
    ),
    prediccion_corregida = prediccion_bruta + correccion_sesgo
  ) %>% ungroup()

mejora_por_modelo <- metricas_sesgo_global %>%
  select(modelo, MAE_bruto_global = MAE_bruto, MAE_corregido_global = MAE_corregido)
pron_actual_largo <- pron_actual_largo %>% left_join(mejora_por_modelo, by = "modelo")

# October–December-specific evaluation pooled across all three horizons.
if (exists("metricas_otono") && nrow(prevision_otono) > 0) {
  eval_otono_modelo <- prevision_otono %>%
    group_by(modelo) %>%
    summarise(
      MAE_bruto_otono = mean(error_absoluto_bruto, na.rm = TRUE),
      MAE_corregido_otono = mean(error_absoluto_corregido, na.rm = TRUE),
      n_otono = n(),
      .groups = "drop"
    )
} else {
  eval_otono_modelo <- tibble(
    modelo = character(), MAE_bruto_otono = double(),
    MAE_corregido_otono = double(), n_otono = integer()
  )
}

pron_actual_largo <- pron_actual_largo %>%
  left_join(eval_otono_modelo, by = "modelo") %>%
  mutate(
    mejora_global = !is.na(MAE_corregido_global) & MAE_corregido_global < MAE_bruto_global,
    mejora_otono = if_else(
      !is.na(n_otono) & n_otono >= 6,
      MAE_corregido_otono < MAE_bruto_otono,
      mejora_global
    ),
    recomendacion = if_else(mejora_global & mejora_otono,
                            "Use bias-adjusted forecast", "Use raw forecast"),
    prediccion_recomendada = if_else(
      mejora_global & mejora_otono,
      prediccion_corregida,
      prediccion_bruta
    )
  )

write_csv(pron_actual_largo, file.path(RESULTS_DIR, "ipc_prevision_final_modelos_comparados.csv"))

# Final ranking uses raw backtest MAE; bias correction must not obscure
# that a model performs worse before correction.
mejor_modelo <- metricas %>% slice_min(MAE, n = 1, with_ties = FALSE) %>% pull(modelo)
cat("\n--- Current forecasts from all candidate models (%) ---\n")
print(pron_actual_largo %>%
        select(fecha_objetivo, horizonte, modelo, prediccion_bruta,
               correccion_sesgo, prediccion_corregida, recomendacion,
               prediccion_recomendada) %>%
        mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf)

cat("\n--- Model with the lowest MAE in the extended backtest ---\n")
cat(mejor_modelo, "\n")
cat("Recommended model forecast for Oct–Dec:\n")
print(pron_actual_largo %>% filter(modelo == mejor_modelo) %>%
        select(fecha_objetivo, modelo, prediccion_bruta, correccion_sesgo,
               prediccion_corregida, recomendacion, prediccion_recomendada) %>%
        mutate(across(where(is.numeric), ~ round(.x, 3))), n = Inf)

cat("\n--- Generated files ---\n")
cat("ipc_modelos_ampliados_backtest.csv\n")
cat("ipc_metricas_modelos_ampliados.csv\n")
cat("ipc_metricas_por_horizonte_ampliado.csv\n")
cat("ipc_evaluacion_correccion_sesgo_ampliada.csv\n")
cat("ipc_resumen_correccion_modelos_ampliados.csv\n")
cat("ipc_valores_reales_oct_nov_dic_por_ano.csv\n")
cat("ipc_backtest_oct_nov_dic_por_ano.csv\n")
cat("ipc_metricas_backtest_oct_nov_dic.csv (when data are available)\n")
cat("ipc_prevision_final_modelos_comparados.csv\n")
cat("\nAnalysis complete. Output folder: ", getwd(), "\n", sep = "")
